std::optional<core::Annotation> copiedStyle;
auto Values(const core::Annotation& a){return std::make_tuple(a.font,a.color,a.background,a.outline,a.width,a.fontSize,a.opacity,a.alpha,a.lineStyle,a.alignment,a.mosaicStrength,a.mosaicMode,a.eraseMode,a.magnification,a.bold,a.italic,a.underline,a.filled,a.shadow,a.textBackground,a.textOutline,a.sampling,a.brightness,a.contrast,a.pictureAdjust,a.textPadding,a.textLineSpacing,a.textAutoHeight,a.pictureMask,a.pictureRadius,a.startHead,a.endHead,a.headSize,a.highlightBlend,a.strokeOpacity,a.fillOpacity,a.effectBrush);}
