bool EditorFrame::ProductivityForm(FormDialog& form){const HWND host=m_hWnd;const auto revision=revision_;const auto ids=Selection();const auto audit=productivityFormAudit_;screenColorModal_=true;INT_PTR result=IDCANCEL;try{result=audit?audit(form):form.Run();}catch(...){if(::IsWindow(host)&&CWnd::FromHandlePermanent(host)==this)screenColorModal_=false;throw;}if(!::IsWindow(host)||CWnd::FromHandlePermanent(host)!=this)return false;screenColorModal_=false;return result==IDOK&&revision==revision_&&ids==Selection();}
void EditorFrame::ProductivityCommand(UINT id){
    if(id==GridSettings){FormDialog form(this,Text::GridSettings,{{Text::GridVisible,Number(gridVisible_),FieldKind::Check},{Text::GridSnap,Number(gridSnap_),FieldKind::Check},{Text::GridStep,Number(gridStep_)}});if(!ProductivityForm(form))return;const int step=Range(form.Fields()[2],1,1024);gridVisible_=form.Fields()[0].Checked();gridSnap_=form.Fields()[1].Checked();gridStep_=step;ClearSnapping();InvalidateRect(canvas_,FALSE);return;}
    if(id==CloneSource){ChangeTool(static_cast<int>(core::Tool::CloneBrush));if(style_.tool==core::Tool::CloneBrush){clonePicking_=true;status_.SetWindowText(Tr(Text::CloneHelp));}return;}
    if(id>=ArrowOneBend&&id<=ArrowVertical){auto ids=Selection();if(ids.size()==1&&document_.State().objects[ids[0]].tool==core::Tool::ElbowArrow){if(!GuardSelection(true))return;auto a=document_.State().objects[ids[0]];const int bends=id==ArrowOneBend?1:id==ArrowTwoBends?2:a.elbowBends;const bool vertical=id==ArrowVertical?true:id==ArrowHorizontal?false:a.elbowVertical;if(bends==a.elbowBends&&vertical==a.elbowVertical)return;a.elbowBends=bends;a.elbowVertical=vertical;core::StartElbowArrow(a,a.points.front(),a.points.back());document_.Replace(ids[0],a);Changed();SyncStyle();return;}ChangeTool(static_cast<int>(core::Tool::ElbowArrow));if(style_.tool!=core::Tool::ElbowArrow)return;if(id==ArrowOneBend||id==ArrowTwoBends)style_.elbowBends=id==ArrowOneBend?1:2;else style_.elbowVertical=id==ArrowVertical;return;}
    const auto ids=Selection();
    if(id==CopyStyle){if(ids.size()!=1||!VisibleSelection()){status_.SetWindowText(Tr(Text::StyleSelectOne));return;}const auto& a=document_.State().objects[ids[0]];copiedStyle=services::StyleTemplate(a);status_.SetWindowText(Tr(Text::StyleCopied));return;}
    if(id==PasteStyle){if(!copiedStyle||ids.empty()||!VisibleSelection()){status_.SetWindowText(Tr(Text::StyleSelectOne));return;}if(!GuardSelection())return;auto state=document_.State();for(int i:ids)if(state.objects[i].tool!=copiedStyle->tool||state.objects[i].effectBrush!=copiedStyle->effectBrush){status_.SetWindowText(Tr(Text::StyleSameTool));return;}bool changed=false;for(int i:ids){auto& a=state.objects[i];const auto before=Values(a);auto runs=a.textRuns;services::CopyToolStyle(*copiedStyle,a);a.textRuns=std::move(runs);changed=changed||before!=Values(a);}if(changed)CommitComposition(std::move(state),ids);return;}
    if(id==PrivacyMosaic||id==ClassicMosaic){if(ids.size()==1&&document_.State().objects[ids[0]].tool==core::Tool::Mosaic){if(!GuardSelection(true))return;auto a=document_.State().objects[ids[0]];if(a.mosaicMode==int(id==PrivacyMosaic))return;a.mosaicMode=id==PrivacyMosaic;document_.Replace(ids[0],a);Changed();SyncStyle();}else ChangeTool(static_cast<int>(core::Tool::Mosaic));style_.mosaicMode=id==PrivacyMosaic;status_.SetWindowText(Tr(id==PrivacyMosaic?Text::PrivacyMosaicHelp:Text::Mosaic));return;}
    if(ids.size()!=1||!VisibleSelection()||!GuardSelection(true))return;const int index=ids[0];auto a=document_.State().objects[index];if(a.tool!=core::Tool::Picture||a.group){status_.SetWindowText(Tr(Text::PictureSingle));return;}
    if(id==PictureAdjust||id==PictureAdjustBypass){if(id==PictureAdjustBypass)a.pictureAdjust=!a.pictureAdjust;else{FormDialog form(this,Text::PictureAdjust,{{Text::Brightness,Number(a.brightness)},{Text::Contrast,Number(a.contrast)},{Text::PictureAdjustEnabled,Number(a.pictureAdjust),FieldKind::Check}});if(!ProductivityForm(form))return;const auto& f=form.Fields();a.brightness=Range(f[0],-100,100);a.contrast=Range(f[1],-100,100);a.pictureAdjust=f[2].Checked();}if(Values(a)==Values(document_.State().objects[index]))return;document_.Replace(index,std::move(a));Changed();SyncStyle();return;}
    if(id!=ReplacePicture)return;FormDialog form(this,Text::ReplacePicture,{{Text::PictureFit,L"0",FieldKind::Choice,{Tr(Text::PictureFitInside),Tr(Text::PictureStretch),Tr(Text::PictureCover)}}});if(!ProductivityForm(form))return;const int mode=Range(form.Fields()[0],0,2);const HWND host=m_hWnd;const auto revision=revision_;CString path;const auto audit=replacementPathAudit_;screenColorModal_=true;try{if(audit)path=audit();else{CFileDialog file(TRUE,L"png",nullptr,OFN_FILEMUSTEXIST,ImageOpenFilter(),this);if(file.DoModal()==IDOK)path=file.GetPathName();}}catch(...){if(::IsWindow(host)&&CWnd::FromHandlePermanent(host)==this)screenColorModal_=false;throw;}if(!::IsWindow(host)||CWnd::FromHandlePermanent(host)!=this)return;screenColorModal_=false;if(path.IsEmpty()||revision!=revision_||ids!=Selection())return;auto state=document_.State();activeAction_=WorkProductivity;StartWork([state=std::move(state),revision,ids,index,path,mode]()mutable{WorkResult r;r.action=WorkProductivity;r.command=ReplacePicture;r.revision=revision;r.expected=ids;core::Image image;if(services::CaptureService::Load(path,image,r.error)){state.objects[index]=core::ReplacePicture(state.objects[index],std::move(image),mode);r.state=std::move(state);}return r;});
}
bool EditorFrame::CloneDown(CPoint point){if(style_.tool!=core::Tool::CloneBrush)return false;if(clonePending_){status_.SetWindowText(Tr(Text::Busy));return true;}const auto bounds=ScreenRect({0,0,document_.Width(),document_.Height()});if(!bounds.PtInRect(point))return true;const auto q=ImagePoint(point);if(clonePicking_||GetKeyState(VK_MENU)<0){cloneSource_=q;clonePicking_=false;status_.SetWindowText(Tr(Text::CloneReady));return true;}if(cloneSource_.x<0||cloneSource_.y<0||cloneSource_.x>=document_.Width()||cloneSource_.y>=document_.Height()){status_.SetWindowText(Tr(Text::CloneHelp));return true;}selected_=-1;selectedObjects_.clear();start_=q;draft_=style_;draft_.points={q};draft_.rect=CRect(q,q);draft_.focus=cloneSource_;clickCandidate_=-1;dragging_=true;SetCapture();return true;}
void EditorFrame::StartCloneCommit(){if(!clonePending_||job_.Busy()||screenColorModal_)return;auto stroke=std::move(*clonePending_);clonePending_.reset();if(cloneRevision_!=revision_){status_.SetWindowText(Tr(Text::Busy));return;}auto state=document_.State();const auto revision=revision_;activeAction_=WorkProductivity;renderPending_=false;StartWork([state=std::move(state),stroke=std::move(stroke),revision]()mutable{WorkResult r;r.action=WorkProductivity;r.command=CloneSource;r.revision=revision;core::Image source;if(services::RenderDocument(state,source,r.error)){auto patch=core::ClonePatch(source,stroke);if(state.objects.size()>=10000)throw std::runtime_error("Object limit (10000)");state.objects.push_back(std::move(patch));r.state=std::move(state);}return r;});}
void EditorFrame::CompleteProductivity(WorkResult& r){if(r.revision!=revision_||r.command==ReplacePicture&&r.expected!=Selection()||!r.state.base){status_.SetWindowText(Tr(Text::Busy));return;}const auto ids=r.expected;document_.Commit(std::move(r.state));selected_=-1;selectedObjects_.clear();Changed();if(!ids.empty())SetSelection(ids);else{SyncStyle();Layout();}}
void EditorFrame::PaintGrid(CDC& dc){if(!gridVisible_||gridStep_*zoom_<4)return;const auto r=ScreenRect({0,0,document_.Width(),document_.Height()});const int saved=dc.SaveDC();dc.IntersectClipRect(r);CPen pen(PS_DOT,1,RGB(190,194,199));auto* old=dc.SelectObject(&pen);const int mode=dc.SetBkMode(TRANSPARENT);const auto first=ImagePoint(canvas_.TopLeft());for(int x=(first.x/gridStep_)*gridStep_;x<document_.Width();x+=gridStep_){const auto p=ScreenRect({x,0,x,0}).TopLeft();if(p.x>canvas_.right)break;dc.MoveTo(p.x,std::max(r.top,canvas_.top));dc.LineTo(p.x,std::min(r.bottom,canvas_.bottom));}for(int y=(first.y/gridStep_)*gridStep_;y<document_.Height();y+=gridStep_){const auto p=ScreenRect({0,y,0,y}).TopLeft();if(p.y>canvas_.bottom)break;dc.MoveTo(std::max(r.left,canvas_.left),p.y);dc.LineTo(std::min(r.right,canvas_.right),p.y);}dc.SetBkMode(mode);dc.SelectObject(old);dc.RestoreDC(saved);}
